async def same(p,before):
 after=await snap(p);assert all(after[k]==before[k] for k in FIELDS);return after
async def fixture(p,url,level,marker):
 await p.add_init_script('if(!sessionStorage.getItem('+json.dumps(marker)+')){const a=JSON.parse(localStorage.getItem('+json.dumps(KEY)+')||"{}");localStorage.setItem('+json.dumps(KEY)+',JSON.stringify({...a,version:1,unlocked:Math.max(a.unlocked||1,'+str(level)+'),last:'+str(level)+',tutorialSeen:true,resume:null}));sessionStorage.setItem('+json.dumps(marker)+',"1")}');await load(p,url,True)
async def until(p,predicate,timeout=10):
 end=time.monotonic()+timeout
 while time.monotonic()<end:
  s=await snap(p)
  if predicate(s):return s
  await p.wait_for_timeout(10)
 raise AssertionError('Timed out '+str(await snap(p)))
async def native_hold(p,selector,millis):
 el=p.locator(selector);await el.scroll_into_view_if_needed();r=await el.bounding_box();cd=await p.context.new_cdp_session(p);await cd.send('Input.dispatchTouchEvent',{'type':'touchStart','touchPoints':[{'x':r['x']+r['width']/2,'y':r['y']+r['height']/2}]});await p.wait_for_timeout(millis);await cd.send('Input.dispatchTouchEvent',{'type':'touchEnd','touchPoints':[]});await cd.detach()
